const $ = s => document.querySelector(s);
const uid = () => globalThis.crypto?.randomUUID ? globalThis.crypto.randomUUID() : Date.now().toString(36) + Math.random().toString(36).slice(2);
const escapeHtml = (text='') => String(text).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const normalize = s => String(s || '').trim().toLowerCase();
let state = loadState();
let selectedClassId = state.classes[0]?.id || null;
let pendingQuiz = null, builderQuestions = [], builderSelectedQuestionId = '', activeQuiz = null, activeHelpTab = 'quick', activeBuilderHelpMode = 'guide', activeColorMode = 'presets', lastFocusedElement = null, wholeTimerId = null, questionTimerId = null, builderDraftTimer = null, builderDraftId = '';

function defaultClassIcon(){ return {...DEFAULT_ICON}; }
function normalizeClassIcon(icon={}){ return {...DEFAULT_ICON, ...icon, color:icon.color||DEFAULT_ICON.color, style:icon.style||DEFAULT_ICON.style, shape:icon.shape||DEFAULT_ICON.shape, emoji:icon.emoji||DEFAULT_ICON.emoji, image:icon.image||''}; }
function iconBackground(i){ const c=i.color||DEFAULT_ICON.color; if(i.style==='Solid') return c; if(i.style==='Pattern') return `repeating-linear-gradient(45deg, ${c}, ${c} 8px, rgba(255,255,255,.32) 8px, rgba(255,255,255,.32) 16px)`; return `linear-gradient(135deg, ${c}, var(--brand2))`; }
function iconShapeClass(i){ return {'Circle':'circle','Square':'square','Hexagon':'hexagon'}[i.shape] || 'rounded'; }
function clampRgb(v){ v=Number(v); return Number.isFinite(v)?Math.max(0,Math.min(255,Math.round(v))):0; }
function isHexColor(v){ return /^#[0-9a-f]{6}$/i.test(String(v||'').trim()); }
function hexToRgb(hex){ hex=isHexColor(hex)?hex:DEFAULT_ICON.color; const n=parseInt(hex.slice(1),16); return {r:(n>>16)&255,g:(n>>8)&255,b:n&255}; }
function rgbToHex(r,g,b){ return '#'+[r,g,b].map(v=>clampRgb(v).toString(16).padStart(2,'0')).join(''); }
function syncColorControls(color, source=''){ const hex=isHexColor(color)?color.toLowerCase():DEFAULT_ICON.color; const rgb=hexToRgb(hex); if($('#classIconColor')) $('#classIconColor').value=hex; if($('#classIconHex')&&source!=='hex') $('#classIconHex').value=hex; ['Red','Green','Blue'].forEach((name,idx)=>{ const val=[rgb.r,rgb.g,rgb.b][idx]; const range=$('#classIcon'+name), num=$('#classIcon'+name+'Number'); if(range&&source!==name.toLowerCase()) range.value=val; if(num&&source!==name.toLowerCase()+'Number') num.value=val; }); document.querySelectorAll('[data-icon-color]').forEach(btn=>{ const on=btn.dataset.iconColor.toLowerCase()===hex; btn.classList.toggle('active',on); btn.setAttribute('aria-checked',String(on)); }); return hex; }
function setColorMode(mode='presets'){ activeColorMode=['presets','hex','rgb'].includes(mode)?mode:'presets'; document.querySelectorAll('[data-color-mode]').forEach(btn=>{ const on=btn.dataset.colorMode===activeColorMode; btn.classList.toggle('active',on); btn.setAttribute('aria-selected',String(on)); }); ['presets','hex','rgb'].forEach(m=>$('#color'+m[0].toUpperCase()+m.slice(1)+'Panel')?.classList.toggle('hidden',m!==activeColorMode)); }
function renderColorPalette(){ const wrap=$('#classIconPalette'); if(!wrap) return; wrap.innerHTML=ICON_COLORS.map(c=>`<button class="color-swatch" type="button" role="radio" aria-label="Use color ${c}" aria-checked="false" data-icon-color="${c}" style="--swatch:${c}"></button>`).join(''); wrap.querySelectorAll('[data-icon-color]').forEach(btn=>btn.onclick=()=>{ syncColorControls(btn.dataset.iconColor); updateClassIconPreview(); }); syncColorControls($('#classIconColor')?.value||DEFAULT_ICON.color); setColorMode(activeColorMode); }
function updateColorFromHex(){ const input=$('#classIconHex'); const v=String(input.value||'').trim(); if(isHexColor(v)){ input.setCustomValidity(''); syncColorControls(v,'hex'); updateClassIconPreview(); } else { input.setCustomValidity('Use a 6-digit hex color like #4f46e5.'); } }
function updateColorFromRgb(source=''){ const hex=rgbToHex($('#classIconRed')?.value,$('#classIconGreen')?.value,$('#classIconBlue')?.value); syncColorControls(hex,source); updateClassIconPreview(); }
function renderClassIconHtml(cls, extra=''){ const i=normalizeClassIcon(cls?.icon), content=i.image ? `<img src="${escapeHtml(i.image)}" alt="">` : `<span>${escapeHtml(i.emoji)}</span>`; return `<span class="class-icon ${iconShapeClass(i)} ${extra}" style="background:${escapeHtml(iconBackground(i))}" role="img" aria-label="${escapeHtml((cls?.name||'Class')+' icon')}">${content}</span>`; }
function setClassIconForm(icon=defaultClassIcon()){ icon=normalizeClassIcon(icon); syncColorControls(icon.color); $('#classIconStyle').value=icon.style; $('#classIconShape').value=icon.shape; $('#classIconEmoji').value=icon.emoji; $('#classIconImageData').value=icon.image; updateClassIconPreview(); }
function getClassIconForm(){ const color=syncColorControls($('#classIconColor').value); return normalizeClassIcon({color, style:$('#classIconStyle').value, shape:$('#classIconShape').value, emoji:$('#classIconEmoji').value.trim()||DEFAULT_ICON.emoji, image:$('#classIconImageData').value}); }
function updateClassIconPreview(){ const p=$('#classIconPreview'); if(!p) return; const i=getClassIconForm(); p.className=`class-icon large ${iconShapeClass(i)}`; p.style.background=iconBackground(i); p.innerHTML=i.image ? `<img src="${escapeHtml(i.image)}" alt="">` : `<span>${escapeHtml(i.emoji)}</span>`; }
function resetClassIcon(){ $('#classIconImage').value=''; setClassIconForm(defaultClassIcon()); setClassStatus('Icon reset to default.'); }

function aiQuizContextMarkdown(){ return `# Quiz AI Context for Offline Class & Quiz Studio

This app is offline, browser-only, dependency-free HTML/CSS/JavaScript. It stores classes, materials, quizzes, icon settings, theme, and latest quiz scores in localStorage. No backend, database, CDN, accounts, or internet access are used. Class creation/editing uses a focused local overlay. Class icon colors use Presets, Hex, and RGB tabs that stay synchronized. Quiz attempts use a setup modal for shuffle, display mode, pagination/one-question navigation, whole-quiz timers, and default per-question timers in one-question mode.

## Quiz Markdown rules
Start with required metadata:

\`\`\`md
# Quiz: Quiz Title
Class: Class Name
Time Limit: 20
Points: 50
\`\`\`

Separate each question with \`---\`. Every question needs a supported \`##\` type heading, a \`Q:\` prompt, and answers.

Supported types: Multiple Choice, Multiple Responses/Checkbox, Matching, True or False, Identification, Fill in the Blank, Enumeration.

### Multiple Choice A-Z
Use options \`A.\` through \`Z.\`; answer with one matching letter.

### Multiple Responses / Checkbox
Use options \`A.\` through \`Z.\`; list every correct letter under \`Answers:\` or comma-separate them in \`Answer:\`. Grading requires the exact selected set.

### Matching
Use \`Pairs:\` and bullets in \`Prompt = Match\`, \`Prompt -> Match\`, \`Prompt => Match\`, or \`Prompt: Match\` format. The app shows dropdowns and grades exact matches case-insensitively.

### Short answers
Identification and Fill in the Blank support \`Answer:\` or \`Answers:\` alternatives. Enumeration uses \`Answers:\` bullets and requires all listed items.

## Complete example
\`\`\`md
${sampleQuiz.trim()}
\`\`\`

Do not invent unsupported syntax such as JSON, YAML, tables, per-question points, hints, explanations, media, essays, or ordering unless the app is updated and documented first.`; }
function quickGuideMarkdown(){ return `# Offline Class & Quiz Studio Quick Guide

- Create classes from the Dashboard overlay with tabbed Presets, Hex, and RGB icon color controls, plus style, shape, emoji, or image icons.
- Edit classes in the same focused overlay; cancel/close does not save changes.
- Add notes or attach local material files.
- Upload Markdown quizzes, preview them, save them, take them, and see results.
- Before taking a quiz, choose shuffle, original order, paginated or one-question display, whole-quiz timer, and optional default per-question timer.
- Shuffle applies only to the current attempt. Preview and edit keep the saved/original order.
- Answers are preserved while moving between pages/questions; timers can auto-submit or advance on expiry.
- Build quizzes manually with Multiple Choice A-Z, Multiple Responses, Matching, True/False, Identification, Fill in the Blank, and Enumeration.
- In the builder, switch the question help between Guide and Examples; it updates for the selected question type.
- Use the Data / Backup tab to export a readable JSON backup before import, reset, or major refactors.
- Import currently replaces local app data after confirmation. Reset clears app data but keeps the theme.
- Data stays in this browser profile under ${STORE_KEY}; theme uses ${THEME_KEY}. Current data version: ${DATA_VERSION}.`; }
function sampleDataMarkdown(){ return `# Offline Class & Quiz Studio Sample Data

Load sample data from this tab to replace current local data after confirmation. It includes demo classes, custom icons, materials, and a quiz covering supported question types.

\`\`\`md
${sampleQuiz.trim()}
\`\`\``; }
function dataBackupMarkdown(){ return `# Data / Backup

This tab is for local data safety. It is separate from the Quick Guide, Sample Data, and AI Quiz Context tabs.

## Where data is stored

CQStudio stores classes, materials, quizzes, class icon settings, latest quiz scores, and schema metadata in this browser's localStorage under ${STORE_KEY}.

Data is per browser profile and per device. Opening or deploying the same static app on another device does not sync your classes or quizzes.

Theme preference is stored separately under ${THEME_KEY}.

## Export Data

Use **Export Data** before major edits, imports, resets, browser cleanup, or refactors. The backup is a human-readable JSON file named cqstudio-backup-YYYY-MM-DD.json.

The backup includes app metadata, backup version, export date, current data version, saved state, classes, materials, quizzes, latest scores, icon settings, and theme value.

## Import Data

Use **Import Data** to restore a CQStudio JSON backup. Import is replace-only in this version: it validates and migrates the file, then asks for confirmation before replacing current local app data.

Export current data first if you may need it later. Merge import is not implemented yet.

## Reset All Data

Use **Reset All Data** only when you want to clear CQStudio app data in this browser. Reset asks for two confirmations, clears ${STORE_KEY}, refreshes the UI to an empty state, and keeps the theme preference.

## Backup troubleshooting

- If import fails, confirm the file is valid JSON and came from CQStudio Export Data.
- If data is missing on another device, export from the old device and import on the new device.
- If a hosted deployment looks empty, remember that static deployment does not create cloud sync.
- Keep backup files somewhere safe before clearing browser storage.

Current data version: ${DATA_VERSION}.`; }

function emptyState(){ return {version:DATA_VERSION, classes:[]}; }
function loadState(){ try{ const saved=localStorage.getItem(STORE_KEY); if(saved) return migrateState(JSON.parse(saved)); }catch(e){ console.warn('Could not load saved app data.', e); } return migrateState({classes:sampleClasses()}); }
function migrateState(rawState){ const src=rawState&&typeof rawState==='object'?rawState:{}; const classes=Array.isArray(src.classes)?src.classes:[]; return {...src, version:DATA_VERSION, classes:classes.map(sanitizeClass)}; }
function sanitizeAttempt(attempt,total=0){ const a=attempt&&typeof attempt==='object'?attempt:{}; return {...a,id:String(a.id||uid()),date:String(a.date||new Date().toISOString()),correct:Number(a.correct)||0,total:Number(a.total)||total,percent:Number(a.percent)||0,displayMode:a.displayMode==='one'?'one':'paged',shuffle:!!a.shuffle,timerUsed:!!a.timerUsed,timeSpentSeconds:Math.max(0,Number(a.timeSpentSeconds)||0),details:Array.isArray(a.details)?a.details:[]}; }
function sanitizeClass(classItem){ const c=classItem&&typeof classItem==='object'?classItem:{}; return {...c, id:String(c.id||uid()), name:String(c.name||'Untitled Class'), teacher:String(c.teacher||''), description:String(c.description||''), icon:normalizeClassIcon(c.icon), materials:Array.isArray(c.materials)?c.materials.map(sanitizeMaterial):[], quizzes:Array.isArray(c.quizzes)?c.quizzes.map(sanitizeQuiz):[]}; }
function sanitizeMaterial(material){ const m=material&&typeof material==='object'?material:{}; return {...m, id:String(m.id||uid()), title:String(m.title||m.fileName||'Untitled Material'), body:String(m.body||''), created:String(m.created||m.uploadedDate||new Date().toISOString())}; }
function sanitizeQuiz(quiz){ const q=quiz&&typeof quiz==='object'?quiz:{}; const questions=Array.isArray(q.questions)?q.questions.map(sanitizeQuestion):[]; const clean={...q, id:String(q.id||uid()), title:String(q.title||'Untitled Quiz'), className:String(q.className||''), timeLimit:Number(q.timeLimit)||0, points:Number(q.points)||questions.length, questions, created:String(q.created||new Date().toISOString()),attempts:Array.isArray(q.attempts)?q.attempts.map(a=>sanitizeAttempt(a,questions.length)):[]}; if(q.lastResult&&typeof q.lastResult==='object') clean.lastResult={...q.lastResult, correct:Number(q.lastResult.correct)||0, total:Number(q.lastResult.total)||questions.length, percent:Number(q.lastResult.percent)||0, date:String(q.lastResult.date||'')}; return clean; }
function sanitizeQuestion(question){ const q=question&&typeof question==='object'?question:{}; const type=q.type==='Checkbox'?'Multiple Responses':(TYPES.includes(q.type)?q.type:'Identification'); const answers=Array.isArray(q.answers)?q.answers.map(String):(q.answer?[String(q.answer)]:[]); return {...q, id:String(q.id||uid()), type, prompt:String(q.prompt||'Untitled question'), options:Array.isArray(q.options)?q.options.map((o,i)=>typeof o==='string'?{key:String(letters[i]||'A'),text:o}:({key:String(o?.key||letters[i]||'A').toUpperCase().slice(0,1), text:String(o?.text||'')})).filter(o=>o.text):[], pairs:Array.isArray(q.pairs)?q.pairs.map(p=>Array.isArray(p)?{left:String(p[0]||''),right:String(p[1]||'')}:{left:String(p?.left||''), right:String(p?.right||'')}).filter(p=>p.left&&p.right):[], answer:String(q.answer||answers[0]||''), answers}; }
function normalizeQuestionShape(q){ return sanitizeQuestion(q); }
function saveState(){ state=migrateState(state); localStorage.setItem(STORE_KEY, JSON.stringify(state)); }
function backupPayload(){ const clean=migrateState(state); return {app:'CQStudio', name:'Offline Class & Quiz Studio', backupVersion:BACKUP_VERSION, exportedAt:new Date().toISOString(), storeKey:STORE_KEY, dataVersion:DATA_VERSION, state:clean, theme:localStorage.getItem(THEME_KEY)||document.documentElement.dataset.theme||'light'}; }
function downloadJsonFile(data,filename){ const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})); a.download=filename; a.click(); URL.revokeObjectURL(a.href); }
function exportAllData(){ downloadJsonFile(backupPayload(),`cqstudio-backup-${new Date().toISOString().slice(0,10)}.json`); }
function extractImportState(parsed){ if(parsed?.app==='CQStudio'&&parsed.state) return parsed.state; if(parsed?.state?.classes) return parsed.state; if(parsed?.classes) return parsed; throw new Error('This file does not look like a CQStudio backup.'); }
async function importDataFile(file){ if(!file) return; try{ const text=await file.text(); const parsed=JSON.parse(text); const imported=migrateState(extractImportState(parsed)); if(!Array.isArray(imported.classes)) throw new Error('Backup is missing a classes array.'); const count=imported.classes.length; if(!confirm(`Import will replace current local app data with ${count} class${count===1?'':'es'} from this backup. Export current data first if needed. Continue?`)) return; state=imported; selectedClassId=state.classes[0]?.id||null; pendingQuiz=null; activeQuiz=null; clearAttemptTimers(); saveState(); closeModal('helpModal'); render(); showView('dashboardView'); alert('CQStudio data imported successfully.'); }catch(err){ alert(`Import failed: ${err.message}`); } finally { if($('#importDataFile')) $('#importDataFile').value=''; } }
function resetAllData(){ if(!confirm('Reset All Data clears all local classes, materials, quizzes, icons, and latest scores from this browser. Theme preference will be kept. Export data first if you may need it later. Continue?')) return; if(!confirm('Final confirmation: permanently clear CQStudio app data in this browser?')) return; localStorage.removeItem(STORE_KEY); state=emptyState(); selectedClassId=null; pendingQuiz=null; activeQuiz=null; clearAttemptTimers(); saveState(); closeModal('helpModal'); render(); showView('dashboardView'); alert('CQStudio app data was reset. Theme preference was kept.'); }
function sampleClass(){ return {id:uid(), name:'Biology 101', teacher:'Ms. Rivera', description:'Introductory biology resources and practice quizzes.', icon:{color:'#16a34a',style:'Gradient',shape:'Rounded square',emoji:'🧬',image:''}, materials:[{id:uid(), title:'Welcome notes', body:'Review cell theory, organelles, photosynthesis, and states of matter before taking the sample quiz.', created:new Date().toISOString()}], quizzes:[parseQuizMarkdown(sampleQuiz)]}; }
function sampleClasses(){ const bio=sampleClass(); return [bio,{id:uid(), name:'Study Skills', teacher:'Coach Lee', description:'Planning, notes, and quiz preparation habits.', icon:{color:'#f59e0b',style:'Pattern',shape:'Circle',emoji:'📝',image:''}, materials:[{id:uid(), title:'Weekly study checklist', body:'1. Review notes after class.\n2. Make flashcards.\n3. Take one short practice quiz.', created:new Date().toISOString()}], quizzes:[]}]; }
function currentClass(){ return state.classes.find(c=>c.id===selectedClassId); }
function classSwitcherHtml(context){ if(!state.classes.length) return '<div class="class-switcher empty-state">No classes available. Create a class first.</div>'; const options=state.classes.map(c=>`<option value="${c.id}" ${c.id===selectedClassId?'selected':''}>${escapeHtml(normalizeClassIcon(c.icon).emoji)} ${escapeHtml(c.name)}${c.teacher?' — '+escapeHtml(c.teacher):''}</option>`).join(''); return `<label class="class-switcher">Current class<select onchange="switchClass(this.value,'${context}')">${options}</select></label>`; }
window.switchClass=(id,context='')=>{ selectedClassId=id; pendingQuiz=null; render(); if(context==='quiz') showView('quizView'); else if(context==='class') showView('classView'); };
function showView(id, options={}){ if(!id) return; document.querySelectorAll('.view').forEach(el=>el.classList.remove('active')); document.querySelectorAll('[data-view]').forEach(el=>{ const on=el.dataset.view===id; el.classList.toggle('active',on); el.setAttribute('aria-selected', String(on)); }); $('#'+id).classList.add('active'); if(id==='quizView'&&!options.skipRender) renderQuizList(); }
function applyTheme(theme){ document.documentElement.dataset.theme=theme; localStorage.setItem(THEME_KEY,theme); const dark=theme==='dark'; $('#themeToggleBtn').textContent=dark?'☀️':'🌙'; $('#themeToggleBtn').setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode'); }
function initTheme(){ const pref=window.matchMedia?.('(prefers-color-scheme: dark)').matches?'dark':'light'; applyTheme(localStorage.getItem(THEME_KEY)||pref); }
function setOverlayMode(on){ document.body.classList.toggle('overlay-open',on); ['.app-header','.layout'].forEach(sel=>{ const el=$(sel); if(!el) return; if(on){ el.setAttribute('aria-hidden','true'); if('inert' in el) el.inert=true; } else { el.removeAttribute('aria-hidden'); if('inert' in el) el.inert=false; } }); }
function anyModalOpen(){ return [...document.querySelectorAll('.modal')].some(m=>!m.classList.contains('hidden')); }
function openModal(id){ lastFocusedElement=document.activeElement; $('#'+id).classList.remove('hidden'); setOverlayMode(true); if(id==='helpModal') renderHelpTab(activeHelpTab); const focusable=$('#'+id).querySelector('button,input,select,textarea,[tabindex]:not([tabindex="-1"])'); focusable?.focus(); }
function closeModal(id){ if(id==='builderModal'&&!$('#builderModal').classList.contains('hidden')){const hasChanges=!!($('#builderTitleInput').value||builderQuestions.length||$('#builderPrompt').value);if(hasChanges&&!confirm('Close builder? Your draft is autosaved and can be restored later. Choose Cancel to keep editing.'))return;} $('#'+id).classList.add('hidden'); if(id==='classModal') $('#showClassFormBtn')?.setAttribute('aria-expanded','false'); if(!anyModalOpen()) setOverlayMode(false); lastFocusedElement?.focus?.(); }
function trapModalFocus(e,modal){ const items=[...modal.querySelectorAll('button,input,select,textarea,a,[tabindex]:not([tabindex="-1"])')].filter(el=>!el.disabled&&el.offsetParent!==null); if(!items.length) return; const first=items[0], last=items[items.length-1]; if(e.key==='Tab'&&e.shiftKey&&document.activeElement===first){ e.preventDefault(); last.focus(); } else if(e.key==='Tab'&&!e.shiftKey&&document.activeElement===last){ e.preventDefault(); first.focus(); } }
function helpDoc(tab){
  const docs={
    quick:{title:'Quick Guide', filename:'offline-class-quiz-guide.md', content:quickGuideMarkdown()},
    sample:{title:'Sample Data', filename:'offline-class-quiz-sample-data.md', content:sampleDataMarkdown()},
    ai:{title:'AI Quiz Context', filename:'quiz-ai-context.md', content:aiQuizContextMarkdown()},
    data:{title:'Data Backup Guide', filename:'cqstudio-data-backup-guide.md', content:dataBackupMarkdown()}
  };
  return docs[tab] || docs.quick;
}
function renderHelpTab(tab='quick'){
  const tabKey=['quick','sample','ai','data'].includes(tab)?tab:'quick';
  activeHelpTab=tabKey;
  const doc=helpDoc(tabKey);
  document.querySelectorAll('[data-help-tab]').forEach(btn=>{ const on=btn.dataset.helpTab===tabKey; btn.classList.toggle('active',on); btn.setAttribute('aria-selected',String(on)); });
  $('#helpMarkdownPreview').textContent=doc.content;
  const sampleExtras=tabKey==='sample'?'<button id="modalLoadSampleBtn" class="primary-btn" type="button">Load sample data</button><button id="modalDownloadSampleBtn" class="secondary-btn" type="button">Download sample quiz file</button>':'';
  const dataExtras=tabKey==='data'?'<button id="exportDataBtn" class="primary-btn" type="button">Export Data</button><label class="import-data-label secondary-btn" for="importDataFile">Import Data<input id="importDataFile" class="visually-hidden" type="file" accept=".json,application/json" /></label><button id="resetDataBtn" class="danger-btn" type="button">Reset All Data</button>':'';
  $('#helpTabActions').innerHTML=`<button class="secondary-btn" type="button" onclick="downloadHelpDoc('${tabKey}')">Download ${escapeHtml(doc.title)} Markdown</button>${sampleExtras}${dataExtras}`;
  $('#modalLoadSampleBtn')?.addEventListener('click',loadSampleData);
  $('#modalDownloadSampleBtn')?.addEventListener('click',downloadSampleQuiz);
  $('#exportDataBtn')?.addEventListener('click',exportAllData);
  $('#importDataFile')?.addEventListener('change',e=>importDataFile(e.target.files[0]));
  $('#resetDataBtn')?.addEventListener('click',resetAllData);
}
window.downloadHelpDoc=tab=>{ const doc=helpDoc(tab); downloadMarkdownFile(doc.content,doc.filename); };

function render(){ renderDashboard(); renderClassDetail(); if(!activeQuiz) renderQuizList(); saveState(); }
function completedCount(cls){ return cls.quizzes.filter(q=>q.lastResult).length; }
function renderDashboard(){ $('#classCount').textContent=`${state.classes.length} class${state.classes.length===1?'':'es'}`; const wrap=$('#classCards'); wrap.innerHTML=''; if(!state.classes.length){ wrap.innerHTML='<div class="empty-state">No classes yet. Click Create Class to add your first class.</div>'; return; } state.classes.forEach(cls=>{ const node=$('#classCardTemplate').content.cloneNode(true); node.querySelector('.card-top .avatar').outerHTML=renderClassIconHtml(cls,'avatar'); node.querySelector('.pill').textContent=`${cls.quizzes.length} quizzes`; node.querySelector('h3').textContent=cls.name; node.querySelector('p').textContent=cls.description||'No description yet.'; node.querySelector('.card-stats').textContent=`${cls.materials.length} materials • ${completedCount(cls)} completed`; node.querySelector('button').onclick=()=>{ selectedClassId=cls.id; render(); showView('classView'); }; wrap.appendChild(node); }); }
function renderMaterial(m){ const fileMeta=m.fileName?`<div class="material-meta">📎 ${escapeHtml(m.fileName)} • ${escapeHtml(m.fileType||'unknown')} • ${new Date(m.uploadedDate||m.created).toLocaleString()}</div>`:''; const fileNote=m.fileNote?`<p class="muted">${escapeHtml(m.fileNote)}</p>`:''; const content=m.fileContent?`<pre class="material-content">${escapeHtml(m.fileContent)}</pre>`:''; const note=m.body?`<p>${escapeHtml(m.body)}</p>`:''; return `<article class="list-item"><header><strong>${escapeHtml(m.title)}</strong><button class="danger-btn" onclick="deleteMaterial('${m.id}')">Delete</button></header>${fileMeta}${note}${fileNote}${content}</article>`; }
function renderClassDetail(){ const cls=currentClass(); $('#emptyClassState').classList.toggle('hidden',!!cls); $('#classDetail').classList.toggle('hidden',!cls); if(!cls){ $('#emptyClassState').innerHTML=state.classes.length?`${classSwitcherHtml('class')}<p>Select a class to manage materials and quizzes.</p>`:'No classes yet. Click Create Class to add your first class.'; return; } $('#detailTitle').innerHTML=`${renderClassIconHtml(cls,'heading-icon')}<span>${escapeHtml(cls.name)}</span>`; $('#detailMeta').textContent=`${cls.teacher||'No teacher'} • ${cls.description||'No description'}`; $('#classDetailSwitcher').innerHTML=classSwitcherHtml('class'); $('#materialsList').innerHTML=cls.materials.map(renderMaterial).join('')||'<p class="muted">No materials yet.</p>'; $('#quizzesList').innerHTML=cls.quizzes.map(renderQuizCard).join('')||'<p class="muted">No quizzes saved yet.</p>'; }
function renderQuizList(){ const cls=currentClass(), area=$('#quizArea'); if(!area||activeQuiz) return; if(!cls){ area.className='panel empty-state'; area.innerHTML=state.classes.length?`${classSwitcherHtml('quiz')}<p>Select a class first, then open the Quizzes tab.</p>`:'No classes yet. Click Create Class to add your first class.'; return; } const pending=cls.quizzes.filter(q=>!q.lastResult), done=cls.quizzes.filter(q=>q.lastResult); area.className='panel quiz-center'; area.innerHTML=`<div class="section-heading"><div><p class="eyebrow">Quiz Center</p><h2>${renderClassIconHtml(cls,'inline-icon')}${escapeHtml(cls.name)} quizzes</h2>${classSwitcherHtml('quiz')}</div><button class="primary-btn" onclick="openQuizBuilder()">Create Quiz</button></div><section class="quiz-section"><h3>Not completed</h3><div class="list quiz-card-list">${pending.map(renderQuizCard).join('')||'<p class="muted">No incomplete quizzes.</p>'}</div></section><section class="quiz-section"><h3>Completed</h3><div class="list quiz-card-list">${done.map(renderQuizCard).join('')||'<p class="muted">No completed quizzes yet.</p>'}</div></section>`; }
function renderQuizCard(q){ const status=q.lastResult?`Completed • Latest score ${q.lastResult.correct}/${q.lastResult.total} (${q.lastResult.percent}%)`:'Not completed'; const attempts=q.attempts?.length||0; return `<article class="list-item quiz-card"><header><strong>${escapeHtml(q.title)}</strong><span class="pill">${q.questions.length} questions</span></header><p>${escapeHtml(q.className||currentClass()?.name||'')} • ${q.timeLimit||0} min • ${q.points||q.questions.length} pts</p><p class="material-meta">${status} • ${attempts} attempt${attempts===1?'':'s'}</p><div class="actions"><button class="primary-btn" onclick="takeQuiz('${q.id}')">Take quiz</button><button class="secondary-btn" onclick="previewSavedQuiz('${q.id}')">Preview</button><button class="secondary-btn" onclick="openQuizBuilder('${q.id}')">Edit</button><button class="secondary-btn" onclick="openAttemptHistory('${q.id}')">History</button><button class="danger-btn" onclick="deleteQuiz('${q.id}')">Delete</button></div></article>`; }
function openAttemptHistory(id){ const quiz=findQuiz(id); if(!quiz)return; $('#historyTitle').textContent=`${quiz.title} — Attempts`; const attempts=[...(quiz.attempts||[])].sort((a,b)=>new Date(b.date)-new Date(a.date)); $('#historyContent').innerHTML=attempts.length?attempts.map(a=>`<article class="list-item"><strong>${escapeHtml(new Date(a.date).toLocaleString())}</strong><p>${a.correct}/${a.total} • ${a.percent}% • ${a.displayMode==='one'?'One question at a time':'Paginated'} • ${a.shuffle?'Shuffled':'Original order'} • ${a.timerUsed?'Timer used':'No timer'} • ${Math.floor(a.timeSpentSeconds/60)}m ${a.timeSpentSeconds%60}s</p></article>`).join(''):'<p class="muted">No completed attempts yet.</p>'; $('#clearHistoryBtn').disabled=!attempts.length; $('#clearHistoryBtn').onclick=()=>{if(!attempts.length||!confirm('Clear all attempt history for this quiz?'))return;quiz.attempts=[];quiz.lastResult=null;saveState();render();openAttemptHistory(id);}; openModal('historyModal'); }
window.openAttemptHistory=openAttemptHistory;
function exportResultMarkdown(quiz,attempt){ const lines=[`# ${quiz.title} — Quiz Results`,'',`Class: ${quiz.className||currentClass()?.name||'Unknown'}`,`Completed: ${new Date(attempt.date).toLocaleString()}`,`Score: ${attempt.correct}/${attempt.total} (${attempt.percent}%)`,`Settings: ${attempt.shuffle?'Shuffled':'Original order'}; ${attempt.displayMode==='one'?'One question at a time':'Paginated'}; ${attempt.timerUsed?'timer used':'no timer'}; ${Math.floor(attempt.timeSpentSeconds/60)}m ${attempt.timeSpentSeconds%60}s`,'','## Question Results','']; (attempt.details||[]).forEach((d,i)=>lines.push(`### ${i+1}. ${d.ok?'Correct':'Incorrect'} — ${d.prompt}`,`- Your answer: ${d.value||'(no answer)'}`,`- Correct answer: ${d.correctAnswer||'(not available)'}`,'')); downloadMarkdownFile(lines.join('\n'),'cqstudio-quiz-results.md'); }
window.exportLatestResult=id=>{const q=findQuiz(id)||window.lastResultExport?.quiz,a=q?.attempts?.[q.attempts.length-1]||window.lastResultExport?.attempt;if(q&&a)exportResultMarkdown(q,a);};

function parseQuizMarkdown(md){ const errors=[], parts=md.split(/\n\s*---\s*\n/), header=parts[0]||''; const title=(header.match(/^#\s*Quiz:\s*(.+)$/mi)||[])[1]?.trim(); const className=(header.match(/^Class:\s*(.+)$/mi)||[])[1]?.trim(); const timeLimit=Number((header.match(/^Time Limit:\s*(\d+)/mi)||[])[1]||0); const points=Number((header.match(/^Points:\s*(\d+)/mi)||[])[1]||0); if(!title) errors.push('Missing required title: # Quiz: Your Title'); if(!className) errors.push('Missing required Class field.'); if(!timeLimit) errors.push('Missing or invalid Time Limit.'); const questions=parts.slice(1).map((s,i)=>parseQuestion(s.trim(),i+1,errors)).filter(Boolean); if(!questions.length) errors.push('No valid questions found. Separate each question with --- and include a supported ## type.'); if(errors.length) throw new Error(errors.join('\n')); return {id:uid(), title, className, timeLimit, points:points||questions.length, questions, created:new Date().toISOString()}; }
function detectQuestionType(section){ const aliases=[['Multiple Responses',['multiple responses','multiple response','checkbox']],['Matching',['matching','match pairs']],['Multiple Choice',['multiple choice']],['True or False',['true or false']],['Identification',['identification']],['Fill in the Blank',['fill in the blank']],['Enumeration',['enumeration']]]; const heads=[...section.matchAll(/^##\s*(.+)$/gmi)].map(m=>m[1].trim().toLowerCase()); for(const h of heads){ const found=aliases.find(([,names])=>names.some(n=>h.includes(n))); if(found) return found[0]; } return null; }
function readAnswerList(section){ const line=(section.match(/^Answer:\s*(.+)$/mi)||[])[1]?.trim(); const block=section.split(/^Answers:\s*$/mi)[1]||''; const bullets=[...block.matchAll(/^-\s*(.+)$/gm)].map(m=>m[1].trim()).filter(Boolean); return bullets.length?bullets:(line?line.split(/[,;]/).map(x=>x.trim()).filter(Boolean):[]); }
function readMatchingPairs(text){ return [...text.matchAll(/^-?\s*(.+?)\s*(?:=>|=|->|:)\s*(.+)$/gm)].map(m=>({left:m[1].replace(/^-\s*/, '').trim(), right:m[2].trim()})).filter(p=>p.left&&p.right); }
function optionKeys(o=[]){ return o.map(x=>String(x.key).toUpperCase()); }
function sameSet(a,b){ const A=a.map(normalize).sort(), B=b.map(normalize).sort(); return A.length===B.length && A.every((v,i)=>v===B[i]); }
function parseQuestion(section, number, errors){ if(!section) return null; const type=detectQuestionType(section); if(!type){ if(/^##?\s+/m.test(section)&&!/^Q:\s*/mi.test(section)) return null; errors.push(`Question ${number}: unsupported or missing type heading.`); return null; } const prompt=(section.match(/^Q:\s*(.+)$/m)||[])[1]?.trim(); if(!prompt) errors.push(`Question ${number}: missing Q: prompt.`); const q={id:uid(), type, prompt, options:[], pairs:[], answer:'', answers:[]}; if(type==='Multiple Choice'||type==='Multiple Responses'){ q.options=[...section.matchAll(/^([A-Z])\.\s*(.+)$/gmi)].map(m=>({key:m[1].toUpperCase(), text:m[2].trim()})); q.answers=readAnswerList(section).map(a=>a.toUpperCase()); q.answer=q.answers[0]||''; const keys=optionKeys(q.options); if(q.options.length<2) errors.push(`Question ${number}: ${type.toLowerCase()} needs options.`); if(!q.answers.length) errors.push(`Question ${number}: missing answer letters.`); if(q.answers.some(a=>!/^[A-Z]$/.test(a)||!keys.includes(a))) errors.push(`Question ${number}: answer letters must match options A-Z.`); } else if(type==='Matching'){ q.pairs=readMatchingPairs(section.split(/^Pairs:\s*$/mi)[1]||section); q.answers=q.pairs.map(p=>`${p.left} = ${p.right}`); q.answer=q.answers[0]||''; if(q.pairs.length<2) errors.push(`Question ${number}: matching needs at least two pairs using - Prompt = Match.`); } else { q.answers=readAnswerList(section); q.answer=q.answers[0]||''; if(!q.answers.length) errors.push(`Question ${number}: missing Answer or Answers.`); } return q; }

function answerText(q){ return q.type==='Matching' ? (q.pairs||[]).map(p=>`${p.left} = ${p.right}`).join('; ') : (q.answers?.join(', ')||q.answer||''); }
function renderQuizPreview(quiz,target){ target.innerHTML=quizPreviewHtml(quiz,true); }
function quizPreviewHtml(quiz,showAnswers=false){ return `<div class="quiz-shell preview-shell"><div class="quiz-header"><div><p class="eyebrow">Quiz Preview</p><h2>${escapeHtml(quiz.title)}</h2><p class="muted">${quiz.questions.length} questions • ${quiz.timeLimit||0} minutes • ${quiz.points||quiz.questions.length} points</p></div></div>${quiz.questions.map((q,i)=>previewQuestion(q,i,showAnswers)).join('')}</div>`; }
function previewQuestion(q,i,showAnswers){ let body=''; if(q.options?.length) body=`<div class="quiz-options">${q.options.map(o=>`<div class="option choice-option read-only"><span>${o.key}. ${escapeHtml(o.text)}</span></div>`).join('')}</div>`; else if(q.type==='Matching') body=`<div class="quiz-options matching-preview">${(q.pairs||[]).map(p=>`<div class="option read-only"><strong>${escapeHtml(p.left)}</strong> → ${escapeHtml(p.right)}</div>`).join('')}</div>`; else body=`<p class="muted">Expected answer format: ${q.type==='Enumeration'?'one item per line':'short written answer'}</p>`; return `<article class="question"><p class="pill">${escapeHtml(q.type)}</p><h3>${i+1}. ${escapeHtml(q.prompt)}</h3>${body}${showAnswers?`<p class="correct-answer">Correct: ${escapeHtml(answerText(q))}</p>`:''}</article>`; }
function buildQuizForm(quiz){ return `<div class="quiz-shell"><div class="quiz-header"><div><p class="eyebrow">Quiz Taking</p><h2 id="activeQuizTitle">${escapeHtml(quiz.title)}</h2><p class="muted">${quiz.questions.length} questions • ${quiz.timeLimit||0} minutes • ${quiz.points||quiz.questions.length} points</p></div></div><form id="takeQuizForm">${quiz.questions.map(questionInput).join('')}<button class="primary-btn" type="submit">Submit quiz</button></form></div>`; }
function questionInput(q,i){ if(q.type==='Multiple Choice') return `<fieldset class="question"><legend><strong>${i+1}. ${escapeHtml(q.prompt)}</strong></legend><div class="quiz-options">${q.options.map(o=>`<label class="option choice-option"><input type="radio" name="q${i}" value="${o.key}" required><span>${o.key}. ${escapeHtml(o.text)}</span></label>`).join('')}</div></fieldset>`; if(q.type==='Multiple Responses') return `<fieldset class="question"><legend><strong>${i+1}. ${escapeHtml(q.prompt)}</strong></legend><p class="muted small-text">Select all correct answers.</p><div class="quiz-options">${q.options.map(o=>`<label class="option choice-option"><input type="checkbox" name="q${i}" value="${o.key}"><span>${o.key}. ${escapeHtml(o.text)}</span></label>`).join('')}</div></fieldset>`; if(q.type==='Matching'){ const rights=[...(q.pairs||[]).map(p=>p.right)].sort(()=>Math.random()-.5); return `<fieldset class="question"><legend><strong>${i+1}. ${escapeHtml(q.prompt)}</strong></legend><div class="matching-inputs">${(q.pairs||[]).map((p,j)=>`<label class="matching-row"><span>${escapeHtml(p.left)}</span><select name="q${i}_${j}" required><option value="">Choose match...</option>${rights.map(r=>`<option value="${escapeHtml(r)}">${escapeHtml(r)}</option>`).join('')}</select></label>`).join('')}</div></fieldset>`; } if(q.type==='True or False') return `<fieldset class="question"><legend><strong>${i+1}. ${escapeHtml(q.prompt)}</strong></legend><div class="quiz-options"><label class="option choice-option"><input type="radio" name="q${i}" value="True" required><span>True</span></label><label class="option choice-option"><input type="radio" name="q${i}" value="False"><span>False</span></label></div></fieldset>`; if(q.type==='Enumeration') return `<div class="question"><label><strong>${i+1}. ${escapeHtml(q.prompt)}</strong><textarea name="q${i}" rows="4" required placeholder="One answer per line"></textarea></label></div>`; return `<div class="question"><label><strong>${i+1}. ${escapeHtml(q.prompt)}</strong><input name="q${i}" required placeholder="Your answer" /></label></div>`; }
function gradeQuiz(quiz,form){ const fd=new FormData(form); let correct=0; const details=quiz.questions.map((q,i)=>{ let value=fd.get(`q${i}`)||'', ok=false; if(q.type==='Enumeration'){ const given=String(value).split(/\n|,/).map(normalize).filter(Boolean); ok=q.answers.every(a=>given.includes(normalize(a))); } else if(q.type==='Multiple Responses'){ const given=fd.getAll(`q${i}`); value=given.join(', '); ok=sameSet(given,q.answers||[]); } else if(q.type==='Matching'){ const given=(q.pairs||[]).map((p,j)=>({left:p.left,right:fd.get(`q${i}_${j}`)||''})); value=given.map(g=>`${g.left} = ${g.right}`).join('; '); ok=(q.pairs||[]).every((p,j)=>normalize(p.right)===normalize(given[j].right)); } else if(q.type==='Multiple Choice'||q.type==='True or False') ok=normalize(value)===normalize(q.answer); else ok=(q.answers?.length?q.answers:[q.answer]).some(a=>normalize(value)===normalize(a)); if(ok) correct++; return {q,value,ok}; }); return {correct,total:quiz.questions.length,percent:Math.round(correct/quiz.questions.length*100),details}; }
function shuffleCopy(items){ const a=[...items]; for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]]; } return a; }
function formatTime(ms){ const total=Math.max(0,Math.ceil(ms/1000)), m=Math.floor(total/60), s=String(total%60).padStart(2,'0'); return `${m}:${s}`; }
function clearAttemptTimers(){ clearInterval(wholeTimerId); clearInterval(questionTimerId); wholeTimerId=null; questionTimerId=null; }
function prepareAttemptQuestions(quiz,shuffle=false){ const qs=quiz.questions.map((q,i)=>{ const copy=JSON.parse(JSON.stringify(normalizeQuestionShape(q))); copy.id ||= uid(); copy._originalIndex=i; if(copy.type==='Matching') copy.matchChoices=shuffleCopy((copy.pairs||[]).map(p=>p.right)); return copy; }); return shuffle?shuffleCopy(qs):qs; }
function getAttemptAnswer(q,i){ return activeQuiz?.answers?.[q.id] ?? (q.type==='Multiple Responses'?[]:q.type==='Matching'?[]:''); }
function collectAttemptAnswers(){ if(!activeQuiz) return; const form=$('#takeQuizForm'); if(!form) return; const fd=new FormData(form); activeQuiz.questions.forEach((q,i)=>{ const visible=q.type==='Matching'?form.querySelector(`[name="a${i}_0"]`):form.querySelector(`[name="a${i}"]`); if(!visible) return; if(q.type==='Multiple Responses') activeQuiz.answers[q.id]=fd.getAll(`a${i}`); else if(q.type==='Matching') activeQuiz.answers[q.id]=(q.pairs||[]).map((p,j)=>fd.get(`a${i}_${j}`)||''); else activeQuiz.answers[q.id]=fd.get(`a${i}`)||''; }); }
function attemptQuestionInput(q,i){ const saved=getAttemptAnswer(q,i); if(q.type==='Multiple Choice') return `<fieldset class="question"><legend><strong>${i+1}. ${escapeHtml(q.prompt)}</strong></legend><div class="quiz-options">${q.options.map(o=>`<label class="option choice-option"><input type="radio" name="a${i}" value="${o.key}" ${saved===o.key?'checked':''}><span>${o.key}. ${escapeHtml(o.text)}</span></label>`).join('')}</div></fieldset>`; if(q.type==='Multiple Responses') return `<fieldset class="question"><legend><strong>${i+1}. ${escapeHtml(q.prompt)}</strong></legend><p class="muted small-text">Select all correct answers.</p><div class="quiz-options">${q.options.map(o=>`<label class="option choice-option"><input type="checkbox" name="a${i}" value="${o.key}" ${Array.isArray(saved)&&saved.includes(o.key)?'checked':''}><span>${o.key}. ${escapeHtml(o.text)}</span></label>`).join('')}</div></fieldset>`; if(q.type==='Matching') return `<fieldset class="question"><legend><strong>${i+1}. ${escapeHtml(q.prompt)}</strong></legend><div class="matching-inputs">${(q.pairs||[]).map((p,j)=>`<label class="matching-row"><span>${escapeHtml(p.left)}</span><select name="a${i}_${j}"><option value="">Choose match...</option>${(q.matchChoices||[]).map(r=>`<option value="${escapeHtml(r)}" ${Array.isArray(saved)&&saved[j]===r?'selected':''}>${escapeHtml(r)}</option>`).join('')}</select></label>`).join('')}</div></fieldset>`; if(q.type==='True or False') return `<fieldset class="question"><legend><strong>${i+1}. ${escapeHtml(q.prompt)}</strong></legend><div class="quiz-options"><label class="option choice-option"><input type="radio" name="a${i}" value="True" ${saved==='True'?'checked':''}><span>True</span></label><label class="option choice-option"><input type="radio" name="a${i}" value="False" ${saved==='False'?'checked':''}><span>False</span></label></div></fieldset>`; if(q.type==='Enumeration') return `<div class="question"><label><strong>${i+1}. ${escapeHtml(q.prompt)}</strong><textarea name="a${i}" rows="4" placeholder="One answer per line">${escapeHtml(saved)}</textarea></label></div>`; return `<div class="question"><label><strong>${i+1}. ${escapeHtml(q.prompt)}</strong><input name="a${i}" value="${escapeHtml(saved)}" placeholder="Your answer" /></label></div>`; }
function gradeAttempt(){ collectAttemptAnswers(); let correct=0; const details=activeQuiz.questions.map((q,i)=>{ let value=activeQuiz.answers[q.id]??'', ok=false; if(q.type==='Enumeration'){ const given=String(value).split(/\n|,/).map(normalize).filter(Boolean); ok=q.answers.every(a=>given.includes(normalize(a))); } else if(q.type==='Multiple Responses'){ const given=Array.isArray(value)?value:[]; value=given.join(', '); ok=sameSet(given,q.answers||[]); } else if(q.type==='Matching'){ const given=(q.pairs||[]).map((p,j)=>({left:p.left,right:(activeQuiz.answers[q.id]||[])[j]||''})); value=given.map(g=>`${g.left} = ${g.right}`).join('; '); ok=(q.pairs||[]).every((p,j)=>normalize(p.right)===normalize(given[j].right)); } else if(q.type==='Multiple Choice'||q.type==='True or False') ok=normalize(value)===normalize(q.answer); else ok=(q.answers?.length?q.answers:[q.answer]).some(a=>normalize(value)===normalize(a)); if(ok) correct++; return {q,value,ok}; }); return {correct,total:activeQuiz.questions.length,percent:Math.round(correct/activeQuiz.questions.length*100),details}; }
function updateAttemptTimers(){ if(!activeQuiz||activeQuiz.submitted) return; const now=Date.now(); if(activeQuiz.wholeEnd){ const left=activeQuiz.wholeEnd-now; if($('#wholeTimerDisplay')) $('#wholeTimerDisplay').textContent=`Quiz time: ${formatTime(left)}`; if(left<=0){ submitActiveQuiz('Whole-quiz time expired. Your attempt was submitted automatically.'); return; } } if(activeQuiz.questionEnd){ const left=activeQuiz.questionEnd-now; if($('#questionTimerDisplay')) $('#questionTimerDisplay').textContent=`Question time: ${formatTime(left)}`; if(left<=0){ collectAttemptAnswers(); if(activeQuiz.page<activeQuiz.questions.length-1){ activeQuiz.page++; renderAttemptPage(false,'Question time expired. Moving to the next question.'); } else submitActiveQuiz('Question time expired. Your attempt was submitted automatically.'); } } }
function startWholeTimer(){ clearInterval(wholeTimerId); if(activeQuiz?.wholeEnd){ updateAttemptTimers(); wholeTimerId=setInterval(updateAttemptTimers,1000); } }
function startQuestionTimer(){ clearInterval(questionTimerId); if(activeQuiz?.config.questionSeconds&&activeQuiz.config.mode==='one'){ activeQuiz.questionEnd=Date.now()+activeQuiz.config.questionSeconds*1000; updateAttemptTimers(); questionTimerId=setInterval(updateAttemptTimers,1000); } else activeQuiz.questionEnd=null; }
function renderAttemptPage(collect=true, notice=''){ if(!activeQuiz) return; if(collect) collectAttemptAnswers(); const cfg=activeQuiz.config, total=activeQuiz.questions.length, per=cfg.mode==='one'?1:cfg.perPage, pages=Math.ceil(total/per), page=Math.max(0,Math.min(activeQuiz.page,pages-1)); activeQuiz.page=page; const start=page*per, shown=activeQuiz.questions.slice(start,start+per); const progress=cfg.mode==='one'?`Question ${page+1} of ${total}`:`Page ${page+1} of ${pages} • Questions ${start+1}-${Math.min(start+per,total)} of ${total}`; $('#quizOverlayContent').innerHTML=`<div class="quiz-shell"><div class="quiz-header"><div><p class="eyebrow">Quiz Taking</p><h2 id="activeQuizTitle">${escapeHtml(activeQuiz.quiz.title)}</h2><p class="muted">${progress}${cfg.shuffle?' • shuffled attempt':''}</p></div><div class="timer-stack" aria-live="polite"><span id="wholeTimerDisplay" class="pill">${activeQuiz.wholeEnd?'Quiz time: --:--':'No quiz timer'}</span><span id="questionTimerDisplay" class="pill ${cfg.questionSeconds?'':'hidden'}">Question time: --:--</span></div></div>${notice?`<div class="success" role="status">${escapeHtml(notice)}</div>`:''}<form id="takeQuizForm">${shown.map((q,offset)=>attemptQuestionInput(q,start+offset)).join('')}<div class="actions quiz-nav-actions"><button class="ghost-btn" type="button" id="prevQuestionPage" ${page===0?'disabled':''}>Previous</button><button class="secondary-btn" type="button" id="nextQuestionPage" ${page>=pages-1?'disabled':''}>Next</button><button class="primary-btn" type="submit">Submit quiz</button></div></form></div>`; $('#takeQuizForm').onsubmit=e=>{ e.preventDefault(); submitActiveQuiz(); }; $('#prevQuestionPage').onclick=()=>{ activeQuiz.page--; renderAttemptPage(); }; $('#nextQuestionPage').onclick=()=>{ activeQuiz.page++; renderAttemptPage(); }; startQuestionTimer(); updateAttemptTimers(); }
function submitActiveQuiz(notice=''){ if(!activeQuiz||activeQuiz.submitted)return;clearAttemptTimers();const result=gradeAttempt(),quiz=activeQuiz.quiz,id=activeQuiz.id,completedAt=new Date().toISOString(),timeSpentSeconds=Math.max(0,Math.round((Date.now()-activeQuiz.startedAt)/1000)),attempt={id:uid(),date:completedAt,correct:result.correct,total:result.total,percent:result.percent,displayMode:activeQuiz.config.mode,shuffle:activeQuiz.config.shuffle,timerUsed:!!(activeQuiz.config.wholeMinutes||activeQuiz.config.questionSeconds),timeSpentSeconds,details:result.details.map(d=>({prompt:d.q.prompt,value:String(d.value??''),correctAnswer:answerText(d.q),ok:d.ok}))};activeQuiz.submitted=true;quiz.attempts=Array.isArray(quiz.attempts)?quiz.attempts:[];quiz.attempts.push(attempt);quiz.lastResult={correct:result.correct,total:result.total,percent:result.percent,date:completedAt};window.lastResultExport={quiz,attempt};saveState();$('#quizOverlayContent').innerHTML=`<div class="quiz-shell"><p class="eyebrow">Results Summary</p><h2>${escapeHtml(quiz.title)}</h2>${notice?`<div class="success">${escapeHtml(notice)}</div>`:''}<div class="score">${result.correct}/${result.total}</div><p class="muted">Score: ${result.percent}%</p><div class="results-actions"><button class="primary-btn" onclick="takeQuiz('${id}')">Try Again</button><button class="secondary-btn" onclick="exportLatestResult('${id}')">Download Results as Markdown</button><button class="secondary-btn" onclick="window.print()">Print Results</button><button class="ghost-btn" onclick="closeQuizAfterSubmit()">Close</button></div>${result.details.map((d,i)=>`<div class="question ${d.ok?'result-correct':'result-wrong'}"><h4>${i+1}. ${d.ok?'Correct':'Needs review'}</h4><p>${escapeHtml(d.q.prompt)}</p><p>Your answer: ${escapeHtml(String(d.value))}</p><p>Correct answer: ${escapeHtml(answerText(d.q))}</p></div>`).join('')}</div>`; }

function setMaterialStatus(message,type=''){ $('#materialStatus').textContent=message; $('#materialStatus').className=`form-message ${type}`.trim(); }
function setClassStatus(message,type=''){ $('#classStatus').textContent=message; $('#classStatus').className=`form-message ${type}`.trim(); }
function readMaterialFile(file){ return new Promise(resolve=>{ if(!file) return resolve({}); const isText=/\.(txt|md)$/i.test(file.name)||/^text\//.test(file.type); const meta={fileName:file.name,fileType:file.type||file.name.split('.').pop()||'unknown',uploadedDate:new Date().toISOString()}; if(!isText||file.size>180*1024) return resolve({...meta,fileContent:'',fileNote:isText?'Text file was too large to store; metadata saved only.':'Preview not available offline; metadata saved only.'}); const reader=new FileReader(); reader.onload=()=>resolve({...meta,fileContent:String(reader.result||'')}); reader.onerror=()=>resolve({...meta,fileContent:'',fileNote:'Could not read file content; metadata saved only.'}); reader.readAsText(file); }); }
function showClassForm(editing=false){ $('#classModalTitle').textContent=editing?'Edit Class':'Create Class'; $('#classSubmitBtn').textContent=editing?'Save Changes':'Add Class'; $('#showClassFormBtn').setAttribute('aria-expanded','true'); if(!editing){ $('#classForm').reset(); $('#classId').value=''; setClassIconForm(defaultClassIcon()); setClassStatus(''); } openModal('classModal'); setTimeout(()=>$('#className')?.focus(),0); }
function hideClassForm(){ $('#classForm').reset(); $('#classId').value=''; setClassIconForm(defaultClassIcon()); $('#classSubmitBtn').textContent='Add Class'; $('#showClassFormBtn').setAttribute('aria-expanded','false'); closeModal('classModal'); }
function loadSampleData(){ if(confirm('Replace current local data with sample classes, materials, and quizzes?')){ state={classes:sampleClasses()}; selectedClassId=state.classes[0].id; pendingQuiz=null; render(); closeModal('helpModal'); showView('dashboardView'); } }
window.deleteMaterial=id=>{ const cls=currentClass(); cls.materials=cls.materials.filter(m=>m.id!==id); render(); };
window.deleteQuiz=id=>{ const cls=currentClass(); if(confirm('Delete this quiz?')){ cls.quizzes=cls.quizzes.filter(q=>q.id!==id); render(); } };
window.previewSavedQuiz=id=>{ const quiz=findQuiz(id); if(!quiz) return; showView('quizView',{skipRender:true}); $('#quizArea').className='panel quiz-center'; $('#quizArea').innerHTML=`<div class="actions preview-actions sticky-actions"><button class="secondary-btn" onclick="renderQuizList()">Back to quiz list</button><button class="primary-btn" onclick="takeQuiz('${id}')">Take quiz</button><button class="secondary-btn" onclick="openQuizBuilder('${id}')">Edit</button></div>`+quizPreviewHtml(quiz,true); };
function openQuizSetup(id){ const quiz=findQuiz(id); if(!quiz) return; $('#quizSetupId').value=id; $('#quizSetupTitle').textContent=`Start ${quiz.title}`; $('#quizSetupSummary').textContent=`${quiz.questions.length} questions • Saved order is preserved unless you shuffle this attempt only.`; $('#setupShuffle').checked=false; $('#setupWholeTimer').checked=!!quiz.timeLimit; $('#setupWholeMinutes').value=quiz.timeLimit||10; document.querySelector('[name="setupDisplayMode"][value="paged"]').checked=true; $('#setupQuestionsPerPage').value=Math.min(5,Math.max(1,quiz.questions.length)); $('#setupQuestionTimer').checked=false; $('#setupQuestionSeconds').value=60; toggleSetupMode(); openModal('quizSetupModal'); }
function toggleSetupMode(){ const mode=document.querySelector('[name="setupDisplayMode"]:checked')?.value||'paged'; $('#perQuestionSetup').classList.toggle('hidden',mode!=='one'); $('#setupQuestionsPerPage').disabled=mode!=='paged'; }
function startQuizFromSetup(){ const id=$('#quizSetupId').value, quiz=findQuiz(id); if(!quiz) return; const mode=document.querySelector('[name="setupDisplayMode"]:checked')?.value||'paged'; const cfg={shuffle:$('#setupShuffle').checked, mode, perPage:Math.max(1,Math.min(20,Number($('#setupQuestionsPerPage').value)||5)), wholeMinutes:$('#setupWholeTimer').checked?Math.max(1,Number($('#setupWholeMinutes').value)||1):0, questionSeconds:mode==='one'&&$('#setupQuestionTimer').checked?Math.max(10,Number($('#setupQuestionSeconds').value)||60):0}; activeQuiz={id,quiz,questions:prepareAttemptQuestions(quiz,cfg.shuffle),answers:{},page:0,config:cfg,submitted:false,startedAt:Date.now(),wholeEnd:cfg.wholeMinutes?Date.now()+cfg.wholeMinutes*60000:null,questionEnd:null}; closeModal('quizSetupModal'); openModal('quizOverlay'); renderAttemptPage(false); startWholeTimer(); }
window.takeQuiz=id=>openQuizSetup(id);
window.closeQuizAfterSubmit=()=>{ clearAttemptTimers(); activeQuiz=null; closeModal('quizOverlay'); render(); renderQuizList(); };
function findQuiz(id){ return currentClass()?.quizzes.find(q=>q.id===id); }

const BUILDER_HELP = {
  'Multiple Choice': {
    guide: 'Use for one correct answer from A-Z choices. Enter options as A. Text, B. Text, and put one correct letter in Correct answer(s). Grading checks the selected letter exactly. Avoid duplicate letters and answers that do not exist.',
    examples: 'Q: What is the basic unit of life?\nA. Atom\nB. Cell\nC. Tissue\nD. Organ\nAnswer: B'
  },
  'Multiple Responses': {
    guide: 'Use when two or more choices can be correct. Enter A-Z options, then list every correct letter or use comma-separated letters. Grading requires the exact set: no missing and no extra selections.',
    examples: 'Q: Which are states of matter?\nA. Solid\nB. Liquid\nC. Photosynthesis\nD. Gas\nAnswers:\n- A\n- B\n- D'
  },
  'Matching': {
    guide: 'Use for term-to-definition or item-to-match questions. Put pairs in the options box using Term = Match, Term -> Match, Term => Match, or Term: Match. The answer box is hidden because pairs are the answer key. Grading checks each dropdown match.',
    examples: 'Q: Match each organelle to its function.\nPairs:\n- Mitochondria = Produces energy\n- Ribosome = Builds proteins\n- Nucleus = Stores DNA'
  },
  'True or False': {
    guide: 'Use for one statement with a True or False answer. Put True or False in Correct answer(s). Grading is case-insensitive. Avoid adding extra explanation in the answer field.',
    examples: 'Q: Plants perform photosynthesis.\nAnswer: True'
  },
  'Identification': {
    guide: 'Use for short written recall. Enter one accepted answer, or multiple accepted answers on separate lines. Grading accepts an exact case-insensitive match to any listed answer.',
    examples: 'Q: What organelle is known as the powerhouse of the cell?\nAnswers:\n- Mitochondria\n- the mitochondria'
  },
  'Fill in the Blank': {
    guide: 'Use for a sentence with a missing word or phrase. Put the accepted answer(s) in Correct answer(s). Grading is exact after trimming/case normalization, so include common alternate wording if needed.',
    examples: 'Q: The process by which plants make food is called ____.\nAnswer: photosynthesis'
  },
  'Enumeration': {
    guide: 'Use when students must list several items. Enter each required item on its own line. Grading requires every listed item to appear in the student response; order does not matter.',
    examples: 'Q: List three states of matter.\nAnswers:\n- Solid\n- Liquid\n- Gas'
  }
};
function renderBuilderHelp(){ const type=$('#builderType')?.value||'Multiple Choice', mode=activeBuilderHelpMode; document.querySelectorAll('[data-builder-help]').forEach(btn=>{ const on=btn.dataset.builderHelp===mode; btn.classList.toggle('active',on); btn.setAttribute('aria-selected',String(on)); }); const doc=BUILDER_HELP[type]||BUILDER_HELP['Identification']; if($('#builderHelpContent')) $('#builderHelpContent').textContent=doc[mode]||doc.guide; }
function setBuilderHelpMode(mode){ activeBuilderHelpMode=mode==='examples'?'examples':'guide'; renderBuilderHelp(); }

function readBuilderDraft(){try{return JSON.parse(localStorage.getItem(BUILDER_DRAFT_KEY)||'null')}catch{return null}}
function updateDraftActions(){const d=readBuilderDraft();$('#builderDraftActions').classList.toggle('hidden',!d);}
function scheduleBuilderDraftSave(){clearTimeout(builderDraftTimer);builderDraftTimer=setTimeout(saveBuilderDraft,BUILDER_DRAFT_DELAY);}
function saveBuilderDraft(){if(!$('#builderModal')||$('#builderModal').classList.contains('hidden'))return;const draft={id:builderDraftId||uid(),quizId:$('#builderQuizId').value,title:$('#builderTitleInput').value,time:$('#builderTime').value,points:$('#builderPoints').value,questions:builderQuestions,selectedQuestionId:builderSelectedQuestionId,editor:{index:$('#builderQuestionIndex').value,type:$('#builderType').value,prompt:$('#builderPrompt').value,options:$('#builderOptions').value,answers:$('#builderAnswers').value},savedAt:new Date().toISOString()};try{localStorage.setItem(BUILDER_DRAFT_KEY,JSON.stringify(draft));builderDraftId=draft.id;updateDraftActions()}catch(error){console.warn('Could not save quiz builder draft.',error)}}
function restoreBuilderDraft(){const d=readBuilderDraft();if(!d)return;builderDraftId=d.id||uid();$('#builderQuizId').value=d.quizId||'';$('#builderTitleInput').value=d.title||'';$('#builderTime').value=d.time||10;$('#builderPoints').value=d.points||10;builderQuestions=Array.isArray(d.questions)?d.questions.map(normalizeQuestionShape):[];builderSelectedQuestionId=d.selectedQuestionId||'';const e=d.editor||{};$('#builderQuestionIndex').value=e.index??'';$('#builderType').value=e.type||'Multiple Choice';$('#builderPrompt').value=e.prompt||'';$('#builderOptions').value=e.options||'';$('#builderAnswers').value=e.answers||'';$('#questionEditorTitle').textContent=$('#builderQuestionIndex').value===''?'Add question':'Edit question';$('#addQuestionBtn').textContent=$('#builderQuestionIndex').value===''?'Add Question':'Update Question';toggleBuilderOptions();renderBuilderQuestions();}
function discardBuilderDraft(){if(!confirm('Discard the saved quiz builder draft?'))return;localStorage.removeItem(BUILDER_DRAFT_KEY);builderDraftId='';updateDraftActions();}
function openQuizBuilder(quizId=''){const cls=currentClass();if(!cls){alert('Select a class before creating a quiz.');return;}const draft=readBuilderDraft();if(draft&&confirm('A saved quiz builder draft exists. Restore it? Choose Cancel to start fresh.')){restoreBuilderDraft();openModal('builderModal');return;}const quiz=quizId?cls.quizzes.find(q=>q.id===quizId):null;builderDraftId=uid();$('#builderQuizId').value=quizId;$('#builderTitle').textContent=quiz?'Edit Quiz':'Create Quiz';$('#builderTitleInput').value=quiz?.title||'';$('#builderTime').value=quiz?.timeLimit||10;$('#builderPoints').value=quiz?.points||10;builderQuestions=quiz?JSON.parse(JSON.stringify(quiz.questions.map(normalizeQuestionShape))):[];builderQuestions.forEach(q=>q.id ||= uid());builderSelectedQuestionId=builderQuestions[0]?.id||'';clearQuestionEditor();if(builderQuestions.length)editBuilderQuestion(0);else renderBuilderQuestions();openModal('builderModal');scheduleBuilderDraftSave();}
window.openQuizBuilder=openQuizBuilder;
function shortPreview(text){ const clean=String(text||'').replace(/\s+/g,' ').trim(); return clean.length>72?clean.slice(0,69)+'...':clean||'Untitled question'; }
function renderBuilderQuestions(){ $('#builderQuestionList').innerHTML=builderQuestions.map((q,i)=>`<article class="builder-question-item ${q.id===builderSelectedQuestionId?'active':''}" draggable="true" ondragstart="startQuestionDrag(event,${i})" ondragover="event.preventDefault()" ondrop="dropQuestion(event,${i})" aria-current="${q.id===builderSelectedQuestionId?'true':'false'}"><button type="button" class="builder-question-main" onclick="editBuilderQuestion(${i})" aria-label="Edit question ${i+1}: ${escapeHtml(shortPreview(q.prompt))}"><span class="pill">#${i+1}</span><strong>${escapeHtml(q.type)}</strong><span>${escapeHtml(shortPreview(q.prompt))}</span></button><div class="builder-question-actions"><button type="button" class="ghost-btn" onclick="moveBuilderQuestion(${i},-1)" ${i===0?'disabled':''} aria-label="Move question ${i+1} up">Move Up</button><button type="button" class="ghost-btn" onclick="moveBuilderQuestion(${i},1)" ${i===builderQuestions.length-1?'disabled':''} aria-label="Move question ${i+1} down">Move Down</button><button type="button" class="danger-btn" onclick="removeBuilderQuestion(${i})" aria-label="Remove question ${i+1}">Remove</button></div></article>`).join('')||'<p class="muted">No questions yet. Add one in the editor.</p>'; }
function clearQuestionEditor(){ $('#builderQuestionIndex').value=''; $('#builderType').value='Multiple Choice'; $('#builderPrompt').value=''; $('#builderOptions').value=''; $('#builderAnswers').value=''; $('#questionEditorTitle').textContent='Add question'; $('#addQuestionBtn').textContent='Add Question'; activeBuilderHelpMode='guide'; toggleBuilderOptions(); }
window.editBuilderQuestion=i=>{ const q=builderQuestions[i]; if(!q) return; builderSelectedQuestionId=q.id; $('#builderQuestionIndex').value=i; $('#builderType').value=q.type; $('#builderPrompt').value=q.prompt; $('#builderOptions').value=q.type==='Matching' ? (q.pairs||[]).map(p=>`${p.left} = ${p.right}`).join('\n') : (q.options?.map(o=>`${o.key}. ${o.text}`).join('\n')||''); $('#builderAnswers').value=(q.answers?.length?q.answers:[q.answer]).join('\n'); $('#questionEditorTitle').textContent=`Edit question ${i+1}`; $('#addQuestionBtn').textContent='Update Question'; toggleBuilderOptions(); renderBuilderQuestions(); };
window.removeBuilderQuestion=i=>{ const removed=builderQuestions.splice(i,1)[0]; if(removed?.id===builderSelectedQuestionId){ const next=Math.min(i,builderQuestions.length-1); if(next>=0) editBuilderQuestion(next); else{ builderSelectedQuestionId=''; clearQuestionEditor(); renderBuilderQuestions(); } return; } renderBuilderQuestions(); };
window.moveBuilderQuestion=(i,dir)=>{ const to=i+dir; if(to<0||to>=builderQuestions.length) return; const selectedId=builderSelectedQuestionId; [builderQuestions[i],builderQuestions[to]]=[builderQuestions[to],builderQuestions[i]]; builderSelectedQuestionId=selectedId; const ni=builderQuestions.findIndex(q=>q.id===selectedId); if(ni>=0&&$('#builderQuestionIndex').value!=='') $('#builderQuestionIndex').value=ni; renderBuilderQuestions(); };
window.startQuestionDrag=(event,i)=>{ event.dataTransfer.setData('text/plain',String(i)); event.dataTransfer.effectAllowed='move'; };
window.dropQuestion=(event,to)=>{ event.preventDefault(); const from=Number(event.dataTransfer.getData('text/plain')); if(Number.isNaN(from)||from===to) return; const selectedId=builderSelectedQuestionId||builderQuestions[from]?.id; const [moved]=builderQuestions.splice(from,1); builderQuestions.splice(to,0,moved); builderSelectedQuestionId=selectedId; const ni=builderQuestions.findIndex(q=>q.id===selectedId); if(ni>=0&&$('#builderQuestionIndex').value!=='') $('#builderQuestionIndex').value=ni; renderBuilderQuestions(); };
function toggleBuilderOptions(){ const type=$('#builderType').value; const show=['Multiple Choice','Multiple Responses','Matching'].includes(type); $('#builderOptionsWrap').classList.toggle('hidden',!show); $('#builderOptionsWrap').childNodes[0].nodeValue=type==='Matching'?'Matching pairs':'Options / matching pairs'; $('#builderAnswers').closest('label').classList.toggle('hidden',type==='Matching'); renderBuilderHelp(); }
function buildQuestionFromEditor(){ const type=$('#builderType').value, prompt=$('#builderPrompt').value.trim(), rawAnswers=$('#builderAnswers').value.split(/\n|,/).map(s=>s.trim()).filter(Boolean); if(!prompt) throw new Error('Question prompt is required.'); const idxRaw=$('#builderQuestionIndex').value, existing=idxRaw===''?null:builderQuestions[Number(idxRaw)]; const q={id:existing?.id||uid(), type, prompt, options:[], pairs:[], answer:rawAnswers[0]||'', answers:rawAnswers}; if(type==='Multiple Choice'||type==='Multiple Responses'){ q.options=$('#builderOptions').value.split(/\n/).map((line,idx)=>{ const m=line.match(/^([A-Z])\.\s*(.+)$/i); return m?{key:m[1].toUpperCase(),text:m[2].trim()}:{key:letters[idx],text:line.trim()}; }).filter(o=>o.text).slice(0,26); q.answers=rawAnswers.map(a=>a.toUpperCase()); q.answer=q.answers[0]||''; const keys=optionKeys(q.options); if(q.options.length<2||!q.answers.length||q.answers.some(a=>!/^[A-Z]$/.test(a)||!keys.includes(a))) throw new Error(`${type} needs at least two options and answer letters matching options A-Z.`); } else if(type==='Matching'){ q.pairs=readMatchingPairs($('#builderOptions').value); q.answers=q.pairs.map(p=>`${p.left} = ${p.right}`); q.answer=q.answers[0]||''; if(q.pairs.length<2) throw new Error('Matching needs at least two pairs, for example: Term = Definition.'); } else if(!rawAnswers.length) throw new Error('Question prompt and answer are required.'); return q; }

function initApp(){
  $('#classForm').addEventListener('submit',e=>{ e.preventDefault(); const id=$('#classId').value; const data={name:$('#className').value.trim(), teacher:$('#classTeacher').value.trim(), description:$('#classDescription').value.trim(), icon:getClassIconForm()}; if(!data.name){ setClassStatus('Please enter a class name.','error-text'); return; } if(id) Object.assign(state.classes.find(c=>c.id===id),data); else{ selectedClassId=uid(); state.classes.unshift({id:selectedClassId,...data,materials:[],quizzes:[]}); } hideClassForm(); render(); showView('dashboardView'); });
  $('#showClassFormBtn').onclick=()=>{ showClassForm(false); $('#className').focus(); };
  $('#cancelEditClass').onclick=()=>{ hideClassForm(); setClassStatus(''); };
  $('#editClassBtn').onclick=()=>{ const c=currentClass(); showClassForm(true); $('#classId').value=c.id; $('#className').value=c.name; $('#classTeacher').value=c.teacher; $('#classDescription').value=c.description; setClassIconForm(c.icon); };
  $('#deleteClassBtn').onclick=()=>{ if(confirm('Delete this class and all its local data?')){ state.classes=state.classes.filter(c=>c.id!==selectedClassId); selectedClassId=state.classes[0]?.id||null; render(); showView('dashboardView'); } };
  $('#materialForm').addEventListener('submit',async e=>{ e.preventDefault(); const cls=currentClass(), title=$('#materialTitle').value.trim(), body=$('#materialBody').value.trim(), file=$('#materialFile').files[0]; if(!title||(!body&&!file)){ setMaterialStatus('Add a title and notes or a file.','error-text'); return; } const fileData=await readMaterialFile(file); cls.materials.unshift({id:uid(),title,body,created:new Date().toISOString(),...fileData}); setMaterialStatus('Material saved locally.','success-text'); e.target.reset(); render(); });
  $('#quizFile').addEventListener('change',e=>{ const file=e.target.files[0]; if(!file) return; const reader=new FileReader(); reader.onload=()=>{ try{ pendingQuiz=parseQuizMarkdown(reader.result); $('#parserMessage').className='success'; $('#parserMessage').textContent='Quiz parsed successfully.'; $('#quizPreview').classList.remove('hidden'); $('#saveQuizBtn').classList.remove('hidden'); renderQuizPreview(pendingQuiz,$('#quizPreview')); }catch(err){ pendingQuiz=null; $('#parserMessage').className='error'; $('#parserMessage').textContent=err.message; $('#quizPreview').classList.add('hidden'); $('#saveQuizBtn').classList.add('hidden'); } }; reader.readAsText(file); });
  $('#saveQuizBtn').onclick=()=>{ if(!pendingQuiz) return; currentClass().quizzes.unshift(pendingQuiz); pendingQuiz=null; $('#quizFile').value=''; $('#quizPreview').classList.add('hidden'); $('#saveQuizBtn').classList.add('hidden'); $('#parserMessage').className='success'; $('#parserMessage').textContent='Quiz saved locally.'; render(); };
  $('#createQuizBtn').onclick=()=>openQuizBuilder(); $('#helpBtn').onclick=()=>openModal('helpModal'); document.querySelectorAll('[data-help-tab]').forEach(btn=>{ btn.onclick=()=>renderHelpTab(btn.dataset.helpTab); btn.onkeydown=e=>{ const tabs=[...document.querySelectorAll('[data-help-tab]')], i=tabs.indexOf(btn); if(e.key==='ArrowRight'||e.key==='ArrowLeft'){ e.preventDefault(); const next=tabs[(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length]; next.focus(); renderHelpTab(next.dataset.helpTab); } }; }); $('#themeToggleBtn').onclick=()=>applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');
  renderColorPalette(); document.querySelectorAll('[data-color-mode]').forEach(btn=>{ btn.onclick=()=>setColorMode(btn.dataset.colorMode); btn.onkeydown=e=>{ const modes=['presets','hex','rgb'], i=modes.indexOf(activeColorMode); if(e.key==='ArrowRight'||e.key==='ArrowLeft'){ e.preventDefault(); const next=modes[(i+(e.key==='ArrowRight'?1:-1)+modes.length)%modes.length]; setColorMode(next); document.querySelector(`[data-color-mode="${next}"]`)?.focus(); } }; }); ['#classIconColor','#classIconStyle','#classIconShape','#classIconEmoji'].forEach(sel=>$(sel).addEventListener('input',()=>{ if(sel==='#classIconColor') syncColorControls($('#classIconColor').value,'picker'); updateClassIconPreview(); })); $('#classIconHex').addEventListener('input',updateColorFromHex); ['Red','Green','Blue'].forEach(name=>{ $('#classIcon'+name).addEventListener('input',()=>updateColorFromRgb(name.toLowerCase())); $('#classIcon'+name+'Number').addEventListener('input',()=>{ const v=clampRgb($('#classIcon'+name+'Number').value); $('#classIcon'+name).value=v; updateColorFromRgb(name.toLowerCase()+'Number'); }); }); $('#resetClassIconBtn').onclick=resetClassIcon; $('#classIconImage').onchange=e=>{ const file=e.target.files[0]; if(!file) return; if(!file.type.startsWith('image/')){ setClassStatus('Icon file must be an image.','error-text'); e.target.value=''; return; } if(file.size>MAX_ICON_IMAGE){ setClassStatus('Icon image is too large. Please use an image under 200 KB.','error-text'); e.target.value=''; return; } const reader=new FileReader(); reader.onload=()=>{ $('#classIconImageData').value=String(reader.result||''); updateClassIconPreview(); setClassStatus('Icon image loaded locally.','success-text'); }; reader.readAsDataURL(file); };
  $('#quizSetupForm').onsubmit=e=>{ e.preventDefault(); startQuizFromSetup(); }; $('#setupResetOrder').onclick=()=>{ $('#setupShuffle').checked=false; }; document.querySelectorAll('[name="setupDisplayMode"]').forEach(r=>r.onchange=toggleSetupMode);
  document.querySelectorAll('[data-close]').forEach(btn=>btn.onclick=()=>btn.dataset.close==='classModal'?hideClassForm():closeModal(btn.dataset.close)); document.querySelectorAll('.modal').forEach(modal=>modal.addEventListener('keydown',e=>{ if(e.key==='Tab') trapModalFocus(e,modal); if(e.key==='Escape'){ if(modal.id==='quizOverlay') $('#closeQuizOverlayBtn').click(); else if(modal.id==='classModal') hideClassForm(); else closeModal(modal.id); } })); $('#closeQuizOverlayBtn').onclick=()=>{ if(activeQuiz&&!activeQuiz.submitted&&!confirm('Leaving will cancel the current attempt. Exit quiz?')) return; clearAttemptTimers(); activeQuiz=null; closeModal('quizOverlay'); render(); renderQuizList(); };
  $('#builderType').onchange=()=>{ activeBuilderHelpMode='guide'; toggleBuilderOptions(); scheduleBuilderDraftSave(); };$('#builderTitleInput').addEventListener('input',scheduleBuilderDraftSave);$('#builderTime').addEventListener('input',scheduleBuilderDraftSave);$('#builderPoints').addEventListener('input',scheduleBuilderDraftSave);['#builderPrompt','#builderOptions','#builderAnswers'].forEach(sel=>$(sel).addEventListener('input',scheduleBuilderDraftSave));$('#restoreBuilderDraftBtn').onclick=restoreBuilderDraft;$('#discardBuilderDraftBtn').onclick=discardBuilderDraft;$('#builderModal').addEventListener('input',scheduleBuilderDraftSave);$('#builderModal').addEventListener('change',scheduleBuilderDraftSave);updateDraftActions(); document.querySelectorAll('[data-builder-help]').forEach(btn=>{ btn.onclick=()=>setBuilderHelpMode(btn.dataset.builderHelp); btn.onkeydown=e=>{ if(e.key==='ArrowRight'||e.key==='ArrowLeft'){ e.preventDefault(); setBuilderHelpMode(btn.dataset.builderHelp==='guide'?'examples':'guide'); document.querySelector(`[data-builder-help="${activeBuilderHelpMode}"]`)?.focus(); } }; }); $('#clearQuestionBtn').onclick=()=>{ builderSelectedQuestionId=''; clearQuestionEditor(); renderBuilderQuestions(); };
  $('#addQuestionBtn').onclick=()=>{ try{ const q=buildQuestionFromEditor(); const idx=$('#builderQuestionIndex').value; let next; if(idx===''){ builderQuestions.push(q); next=builderQuestions.length-1; } else{ builderQuestions[Number(idx)]=q; next=Number(idx); } builderSelectedQuestionId=q.id; editBuilderQuestion(next); $('#builderStatus').textContent='Question saved in builder.'; $('#builderStatus').className='form-message success-text'; }catch(err){ $('#builderStatus').textContent=err.message; $('#builderStatus').className='form-message error-text'; } };
  $('#quizBuilderForm').onsubmit=e=>{ e.preventDefault(); const cls=currentClass(); if(!builderQuestions.length){ $('#builderStatus').textContent='Add at least one question.'; return; } const quiz={id:$('#builderQuizId').value||uid(), title:$('#builderTitleInput').value.trim(), className:cls.name, timeLimit:Number($('#builderTime').value||0), points:Number($('#builderPoints').value||builderQuestions.length), questions:builderQuestions, created:new Date().toISOString()}; if(!quiz.title){ $('#builderStatus').textContent='Quiz title is required.'; return; } const existing=cls.quizzes.findIndex(q=>q.id===quiz.id); if(existing>=0) cls.quizzes[existing]={...cls.quizzes[existing],...quiz}; else cls.quizzes.unshift(quiz); clearTimeout(builderDraftTimer);localStorage.removeItem(BUILDER_DRAFT_KEY);builderDraftId='';closeModal('builderModal'); render(); showView('quizView'); };
  document.querySelectorAll('[data-view]').forEach(t=>{ t.onclick=()=>showView(t.dataset.view); t.onkeydown=e=>{ const tabs=[...document.querySelectorAll('[data-view]')], i=tabs.indexOf(t); if(e.key==='ArrowRight'||e.key==='ArrowLeft'){ e.preventDefault(); const next=tabs[(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length]; next.focus(); showView(next.dataset.view); } }; }); initTheme(); setClassIconForm(defaultClassIcon()); render();
}
function downloadMarkdownFile(content,filename){ const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([content],{type:'text/markdown'})); a.download=filename; a.click(); URL.revokeObjectURL(a.href); }
function downloadSampleQuiz(){ downloadMarkdownFile(sampleQuiz,'sample-biology-quiz.md'); }
function downloadAiQuizContext(){ downloadMarkdownFile(aiQuizContextMarkdown(),'quiz-ai-context.md'); }
if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',initApp); else initApp();
